ton" data-gnre-menu-close>×<span class="gnre-visually-hidden">Fechar navegação</span></button></div><div class="gnre-company"><small>Empresa selecionada no GNRE</small><b><?=gnre_h($context['company_name'])?></b></div><nav class="gnre-nav"><a href="<?=gnre_h(gnre_url())?>"<?=$shellArea==='overview'?' class="active" aria-current="page"':''?>><span class="gnre-nav-icon" aria-hidden="true">⌂</span>Visão geral</a><a href="<?=gnre_h(gnre_url('?view=list'))?>"<?=$shellArea==='guides'?' class="active" aria-current="page"':''?>><span class="gnre-nav-icon" aria-hidden="true">▤</span>Guias</a><a href="<?=gnre_h(gnre_url('?view=new'))?>"<?=$shellArea==='new'?' class="active" aria-current="page"':''?>><span class="gnre-nav-icon" aria-hidden="true">＋</span>Nova guia</a></nav></aside><main class="gnre-workspace"><header class="gnre-topbar"><div><nav class="gnre-breadcrumb" aria-label="Você está em"><ol><li><?=gnre_h($shellTitle)?></li></ol></nav><p class="eyebrow">Empresa ativa</p><h1><?=gnre_h($shellTitle)?></h1></div><form method="post" class="gnre-switch" data-gnre-company-form><input type="hidden" name="csrf" value="<?=gnre_h($csrf)?>"><input type="hidden" name="action" value="select_gnre_company"><select name="gnre_company_id"><?php foreach($_SESSION[GNRE_SESSION]['companies']??[] as $company):?><option value="<?=$company['company_id']?>"<?=$company['company_id']===$context['company_id']?' selected':''?>><?=gnre_h($company['company_name'])?></option><?php endforeach;?></select><button>Trocar</button></form></header><section class="gnre-content">
<?php if(!$guide&&$nav==='new'){require __DIR__.'/guide-draft-flow.php';}elseif(!$guide){?><section class="gnre-panel"><h2>Guias</h2><div class="table-wrap"><table><tr><th>#</th><th>Situação</th><th></th></tr><?php foreach($filtered as $g):?><tr><td><?=$g['GNRE001_Id']?></td><td><?=gnre_h($g['_business'])?></td><td><a href="<?=gnre_h(gnre_guide_url((int)$g['GNRE001_Id']))?>">Abrir</a></td></tr><?php endforeach;?></table></div></section><?php }else{?><section class="gnre-panel guide-operational-header"><div><h2>Guia #<?=$id?></h2><dl class="guide-dl"><dt>UF favorecida</dt><dd><?=gnre_h($guide['GNRE001_UF_Favorecida'])?></dd><dt>Ambiente</dt><dd>Homologação</dd><dt>Situação</dt><dd><span class="guide-status"><?=gnre_h($business)?></span></dd><dt>Total</dt><dd>R$ <?=gnre_h($guide['GNRE001_Valor'])?></dd></dl></div><div class="guide-header-actions"><?php if($officialPdf):?><a class="button" href="<?=gnre_h(gnre_url('?action=download_official_pdf&guide_id='.$id.'&document_id='.(int)$officialPdf['GNRE008_Id']))?>">Baixar PDF oficial</a><?php elseif($pdfEligible):?><form method="post" action="<?=gnre_h(gnre_guide_url($id,'processar'))?>"><input type="hidden" name="csrf" value="<?=gnre_h($csrf)?>"><input type="hidden" name="action" value="obtain_official_pdf"><input type="hidden" name="guide_id" value="<?=$id?>"><button>Obter PDF oficial</button></form><?php else:?><button type="button" disabled title="Disponível após emissão e obtenção do PDF oficial">Baixar PDF oficial</button><?php endif;?></div></section><nav class="guide-tabs" aria-label="Seções da guia"><?php foreach($tabs as $key=>$label):?><a href="<?=gnre_h(gnre_guide_url($id,$key))?>"<?=$guideTab===$key?' aria-current="page"':''?>><?=$label?></a><?php endforeach;?></nav>
<?php if($guideTab==='dados'){require __DIR__.'/guide-draft-flow.php';}elseif($guideTab==='historico'){?><section class="gnre-panel gnre-history"><h2>Histórico</h2><?php if(!$attempts):?><p class="optional-mark">Ainda não há tentativas de transmissão registradas.</p><?php endif;?><?php foreach($attempts as $a):?><?php $stateLabels=['CRIADA'=>'Preparada para transmissão','RECEBIDA'=>'Recebida pelo Portal','REJEITADA'=>'Rejeitada pelo Portal','INCONCLUSIVA'=>'Retorno inconclusivo'];$attemptResult=$resultQueue&&(int)($resultQueue['GNRE005_GNRE004_Id']??0)===(int)$a['GNRE004_Id']&&$storedResult&&$storedResult['valid']?$storedResult:null;$occurredAt=trim((string)($a['GNRE004_Data_Hora_Criacao']??''));$occurredAtTimestamp=strtotime($occurredAt);$occurredAtLabel=$occurredAtTimestamp===false?$occurredAt:date('d/m/Y H:i:s',$occurredAtTimestamp);?><article class="gnre-history-card"><h3>Tentativa <?=gnre_h((string)($a['GNRE004_Sequencia']??'Não informada'))?></h3><dl class="gnre-history-details"><dt>Situação da transmissão</dt><dd><?=gnre_h($stateLabels[(string)($a['GNRE004_Estado']??'')]??'Não informado')?></dd><?php if(trim((string)($a['GNRE004_Recibo']??''))!==''):?><dt>Recibo</dt><dd><?=gnre_h((string)$a['GNRE004_Recibo'])?></dd><?php endif;?><?php if(trim((string)($a['GNRE004_Codigo_Retorno']??''))!==''||trim((string)($a['GNRE004_Descricao_Retorno']??''))!==''):?><dt>Retorno do Portal</dt><dd><?=gnre_h(trim((string)($a['GNRE004_Codigo_Retorno']??'').(trim((string)($a['GNRE004_Codigo_Retorno']??''))!==''&&trim((string)($a['GNRE004_Descricao_Retorno']??''))!==''?' — ':'').(string)($a['GNRE004_Descricao_Retorno']??'')))?></dd><?php endif;?><?php if($occurredAt!==''):?><dt>Data e hora</dt><dd><?=gnre_h($occurredAtLabel)?></dd><?php endif;?><?php if($attemptResult):?><?php foreach($attemptResult['guides'] as $resultGuide):?><dt>Resultado individual</dt><dd><?=gnre_h((string)($resultGuide['description']??'Não informado'))?><?=trim((string)($resultGuide['message']??''))!==''?' — '.gnre_h((string)$resultGuide['message']):''?></dd><?php endforeach;?><?php endif;?></dl></article><?php endforeach;?></section><?php }else{?><section class="gnre-panel" data-gnre-process><article class="gnre-process-step"><h2>1. Validar dados e gerar XML</h2><?php if($guide['GNRE001_Status']==='R'):?><form method="post" action="<?=gnre_h(gnre_guide_url($id,'processar'))?>"><input type="hidden" name="csrf" value="<?=gnre_h($csrf)?>"><input type="hidden" name="action" value="generate_xml"><input type="hidden" name="guide_id" value="<?=$id?>"><button>Gerar e validar XML</button></form><?php endif;?><?php if(is_array($xmlResult)&&!empty($xmlResult['errors'])):?><p class="error">A geração local encontrou impedimentos:</p><ul><?php foreach($xmlResult['errors'] as $e):?><li><?=gnre_h($e)?></li><?php endforeach;?></ul><?php elseif(is_array($xmlResult)):?><p class="success">XML gerado e validado localmente com sucesso.</p><details><summary>Visualizar XML</summary><pre data-generated-xml><?=gnre_h((string)($xmlResult['xml']??''))?></pre></details><button type="button" data-copy-generated-xml>Copiar XML</button><?php endif;?></article><article class="gnre-process-step" data-gnre-transmission><h2>2. Transmitir</h2><?php if(isset($transmitError)):?><p class="error">Não foi possível concluir a transmissão. Nenhuma retransmissão automática foi realizada. Consulte o Histórico.</p><?php elseif(isset($transmitResult)):?><?php $tr=$transmitResult['result']??[];if(($tr['kind']??'')==='received'):?><p class="success">Transmissão aceita pelo Portal. Recibo: <?=gnre_h((string)$tr['receipt'])?>. A guia está pendente; consulte o resultado quando a fila permitir.</p><?php elseif(($tr['kind']??'')==='rejected'):?><p class="error">O Portal rejeitou a recepção da guia. Código <?=gnre_h((string)$tr['code'])?>: <?=gnre_h((string)$tr['description'])?>.</p><?php else:?><p class="error">A transmissão teve retorno inconclusivo. Não é seguro retransmitir automaticamente; consulte o Histórico.</p><?php endif;?><?php elseif($latestAttempt&&$latestAttempt['GNRE004_Estado']==='REJEITADA'):?><p class="error">O Portal rejeitou a recepção da guia. Código <?=gnre_h((string)$latestAttempt['GNRE004_Codigo_Retorno'])?>: <?=gnre_h((string)$latestAttempt['GNRE004_Descricao_Retorno'])?>.</p><?php elseif($latestAttempt&&$latestAttempt['GNRE004_Estado']==='INCONCLUSIVA'):?><p class="error">A última transmissão teve retorno inconclusivo. Não é seguro retransmitir automaticamente; consulte o Histórico.</p><?php endif;?><?php if($canTransmit):?><form method="post" action="<?=gnre_h(gnre_guide_url($id,'processar'))?>" onsubmit="return confirm('Transmitir esta guia em homologação?');"><input type="hidden" name="csrf" value="<?=gnre_h($csrf)?>"><input type="hidden" name="action" value="transmit_homologation"><input type="hidden" name="guide_id" value="<?=$id?>"><button>Transmitir em homologação</button></form><?php else:?><p class="optional-mark">A transmissão será liberada após XML local válido e elegibilidade da guia.</p><button type="button" class="gnre-action-blocked" disabled title="Disponível após validar o XML localmente.">🔒 Transmitir GNRE</button><?php endif;?></article><article class="gnre-process-step"><h2>3. Acompanhar resultado</h2><?php if($consultFlash):?><p class="<?=($consultFlash['outcome']??'')==='exception'?'error':'success'?>"><?=gnre_h(gnre_consult_message($consultFlash))?></p><?php endif;?><p>Estado técnico atual: <?=gnre_h((string)$guide['GNRE001_Status'])?><?= $resultQueue?' · fila '.gnre_h((string)$resultQueue['GNRE005_Situacao']):' · sem fila de consulta'?>.</p><?php if($consultAction['available']):?><form method="post" action="<?=gnre_h(gnre_guide_url($id,'processar'))?>"><input type="hidden" name="csrf" value="<?=gnre_h($csrf)?>"><input type="hidden" name="action" value="consult_result"><input type="hidden" name="guide_id" value="<?=$id?>"><button>Consultar resultado</button></form><?php else:?><button type="button" class="gnre-action-blocked" disabled title="<?=gnre_h($consultAction['reason'])?>">🔒 Consultar resultado</button><p><?=gnre_h($consultAction['reason'])?></p><?php endif;?><?php if($storedResult&&$storedResult['valid']):?><h3>Resultado individual persistido</h3><p>Situação do lote: <?=gnre_h((string)$storedResult['lot']['description'])?></p><?php foreach($storedResult['guides'] as $r):?><article class="gnre-result"><strong>Situação individual da guia: <?=gnre_h($r['description'])?></strong><p><?=gnre_h($r['message'])?></p></article><?php endforeach;?><?php else:?><p class="optional-mark">SOAP de resultado ausente ou inválido.</p><?php endif;?></article></section><?php }}?></section></main></div></body></html>
